package demo.pharma.dashboard;
import demo.pharma.catalog.*; import demo.pharma.employee.*; import demo.pharma.inventory.*; import demo.pharma.payment.*; import demo.pharma.purchase.*; import demo.pharma.supplier.*; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*;
@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController {private final MedicineRepository medicines;private final EmployeeRepository employees;private final SupplierRepository suppliers;private final PurchaseOrderRepository purchases;private final MedicineBatchRepository batches;private final PurchaseInvoiceRepository invoices;
 record View(long totalMedicines,long activeMedicines,long lowStockMedicines,long expiringMedicines,long expiredMedicines,long totalEmployees,long activeEmployees,long totalSuppliers,long pendingPurchaseOrders,long pendingPayments,BigDecimal inventoryValue){}
 @GetMapping @PreAuthorize("hasAuthority('DASHBOARD_VIEW')") View dashboard(){var today=LocalDate.now();var allBatches=batches.findAll();long low=medicines.findAll().stream().filter(m->allBatches.stream().filter(b->b.getMedicine().getId().equals(m.getId())&&b.getExpiryDate().isAfter(today)).map(MedicineBatch::getQuantity).reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(m.getReorderLevel())<0).count();BigDecimal value=allBatches.stream().map(b->b.getPurchasePrice().multiply(b.getQuantity())).reduce(BigDecimal.ZERO,BigDecimal::add);long active=medicines.count((r,q,b)->b.equal(r.get("status"),RecordStatus.ACTIVE));return new View(medicines.count(),active,low,batches.expiring(today,today.plusDays(30)).size(),batches.expired(today).size(),employees.count(),employees.countByStatus(EmployeeStatus.ACTIVE),suppliers.count(),purchases.countByStatus(PurchaseOrderStatus.PENDING_APPROVAL),invoices.countByPaymentStatusNot(PaymentStatus.PAID),value);}}
